import{_ as s,a as n}from"./chunks/section-page-relation-en-dark.Buv4-RWn.js";import{_ as i,a as r}from"./chunks/singleton-vs-collection-en-dark.Dd8cmYD4.js";import{_ as l,m as c,k as d,ah as o,q as e,B as t}from"./chunks/framework.HEc25T99.js";const w=JSON.parse('{"title":"Core concepts","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/getting-started/core-concepts.md","filePath":"src/en/developers/getting-started/core-concepts.md"}'),h={name:"developers/getting-started/core-concepts.md"},p=s+"#light-only",m=n+"#dark-only",u=i+"#light-only",g=r+"#dark-only";function f(_,a,b,k,v,S){return d(),c("div",null,[...a[0]||(a[0]=[o('<h1 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h1><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><p>The basic building block of Creopse is the section, which can be defined as a contextualized and localized content block. Every section has a data structure for organizing its content and parameters for adapting its rendering. See <a href="./../development/sections-widgets.html">Sections &amp; Widgets</a> for how they&#39;re created and structured.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><p>A widget is a static UI block, with no data structure and no content managed from the admin panel — a preloader or a scroll progress bar, for example. Unlike a section, it&#39;s neither editable nor translatable. See <a href="./../development/sections-widgets.html#widgets">Sections &amp; Widgets</a>.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><p>Pages in Creopse are stacks of sections whose position and content can be modified. Each page can contain as many sections as needed, and the content of each section is bound to the page it sits on. The same section can therefore be used across multiple pages with different content, or appear multiple times on the same page. It is also possible to bind a section&#39;s content to its content on another page. See <a href="./../development/pages.html">Pages</a> for the full set of commands and use cases.</p>',7),e("p",null,[e("img",{src:p,alt:"Section / Page relationship"}),e("img",{src:m,alt:"Section / Page relationship"})],-1),o('<h2 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to &quot;Menus&quot;">​</a></h2><p>A menu groups the navigation links for a given location (header, footer...). Components like the Header or Footer only display the items defined through this system rather than hardcoded links, which lets navigation be managed from the admin panel without touching code. See <a href="./../development/menus.html">Menus</a>.</p><h2 id="content-models" tabindex="-1">Content models <a class="header-anchor" href="#content-models" aria-label="Permalink to &quot;Content models&quot;">​</a></h2><p>Content models are data models used to retrieve content tied to the platform&#39;s business context, which can be used throughout the application — for example, services, articles, products, etc. They are accessible from any section on any page. See <a href="./../development/content-models.html">Content Models</a>.</p><h2 id="permalinks" tabindex="-1">Permalinks <a class="header-anchor" href="#permalinks" aria-label="Permalink to &quot;Permalinks&quot;">​</a></h2><p>A permalink associates a public URL prefix with content — a content model item, or a news article/category/tag — and with the page that renders it. Without a permalink, a content model has no reachable detail page, even once that page is already coded. See <a href="./../development/permalinks.html">Permalinks</a>.</p><h2 id="data-structures" tabindex="-1">Data structures <a class="header-anchor" href="#data-structures" aria-label="Permalink to &quot;Data structures&quot;">​</a></h2><p>Data structures are descriptions of the shape of the data that makes up the content of various elements such as sections and content models. They allow Creopse to generate the necessary fields for collecting content data in the administration interface.</p><p>Two types of components are distinguished in data structures:</p><ul><li><strong>Singletons</strong>:</li></ul><p>Components used to retrieve simple content data, such as a title, an image, a text, etc.</p><ul><li><strong>Collections</strong>:</li></ul><p>Components used to retrieve complex and repetitive content data, such as a list of team members, a list of customer testimonials, etc.</p>',13),e("p",null,[e("img",{src:u,alt:"Singleton vs Collection"}),e("img",{src:g,alt:"Singleton vs Collection"})],-1),e("p",null,[t("See "),e("a",{href:"./../development/sections-widgets.html#field-types"},"Field types"),t(" for the complete list of available types, and "),e("a",{href:"./../development/utilities.html"},"Utilities"),t(" for the composables/hooks that consume this data in a component.")],-1)])])}const x=l(h,[["render",f]]);export{w as __pageData,x as default};
